/**
 * Rewrite a formula for a **row permutation** (Issue #7 E-D3 ruling, contract
 * increment #399): sorting moves whole records, so a reference to a cell inside
 * the sorted rectangle must follow the record it pointed at. This is the third
 * rewriting family next to `rewriteRefsOnCopy` (copy offset) and
 * `rewriteRefsOnInsertDelete` (structural shift): a permutation, not a shift.
 *
 * Semantics (Issue #7 comment #396 §2 / #399 §1):
 *
 * - a reference is rewritten only when its row **and** column both lie inside
 *   `rect` (the sorted rectangle); anything else — references to cells outside
 *   the rectangle, formulas outside the rectangle (the caller only passes ones
 *   inside) — stays byte-identical because that data did not move;
 * - the row is mapped through `rowMap: oldRow -> newRow` (0-based); rows absent
 *   from the map (for example a declared header row) are left alone;
 * - `$` markers do not block the row move: a physical data move shifts absolute
 *   references too (contract v1.4 §3), unlike the copy path where `$` is
 *   preserved because nothing physical moved;
 * - a range is rewritten only when **both** endpoints are inside `rect`; the
 *   mapped rows are re-normalized as `min:max` (columns never change);
 * - there is no `#REF!` collapse branch: a permutation is total;
 * - non-formula values and formulas the tokenizer cannot lex are returned
 *   unchanged (same leniency as the other rewriters).
 *
 * Pure function: the input string is not modified.
 *
 * @param {string} formula
 * @param {Map<number, number> | ArrayLike<number> | Record<number, number>} rowMap
 * @param {{ r1: number, c1: number, r2: number, c2: number }} rect
 * @returns {string}
 */
export function rewriteRefsOnRowPermutation(formula, rowMap, rect) {
  if (!formula || typeof formula !== 'string' || !formula.startsWith('=')) return formula;
  if (!rowMap || !rect) return formula;
  const { r1, c1, r2, c2 } = rect;
  if (![r1, c1, r2, c2].every((value) => Number.isFinite(value))) return formula;

  /** @param {number} row @returns {boolean} */
  const inside = (row, col) => row >= r1 && row <= r2 && col >= c1 && col <= c2;

  /** @param {number} row @returns {number | null} */
  const permute = (row) => {
    const mapped =
      typeof (/** @type {Map<number, number>} */ (rowMap).get) === 'function'
        ? /** @type {Map<number, number>} */ (rowMap).get(row)
        : /** @type {Record<number, number>} */ (rowMap)[row];
    return Number.isInteger(mapped) ? /** @type {number} */ (mapped) : null;
  };

  return rewriteFormula(formula, (token, original) => {
    if (token.type === 'ref') {
      const part = token.ref;
      if (!part || !inside(part.row, part.col)) return { collapse: false, text: original };
      const row = permute(part.row);
      if (row === null) return { collapse: false, text: original };
      return { collapse: false, text: formatRefPart(row, part.col, part) };
    }
    const start = token.startPart;
    const end = token.endPart;
    if (!start || !end) return { collapse: false, text: original };
    if (!inside(start.row, start.col) || !inside(end.row, end.col)) {
      return { collapse: false, text: original };
    }
    const startRow = permute(start.row);
    const endRow = permute(end.row);
    if (startRow === null || endRow === null) return { collapse: false, text: original };
    const first = startRow <= endRow ? startRow : endRow;
    const last = startRow <= endRow ? endRow : startRow;
    return {
      collapse: false,
      text: `${formatRefPart(first, start.col, start)}:${formatRefPart(last, end.col, end)}`,
    };
  });
}
```

